function savedVehicleCount(customer:any){let saved:any[]=[],deleted:string[]=[];try{saved=JSON.parse(localStorage.getItem(`aa-garage-vehicles-${customer.id}`)||'[]')}catch{}try{deleted=JSON.parse(localStorage.getItem(`aa-garage-deleted-vehicles-${customer.id}`)||'[]').map((value:string)=>value.toUpperCase())}catch{}return new Set([...(customer.vehicles||[]),...(customer.jobs||[]),...saved].map((item:any)=>String(item.reg||'').trim().toUpperCase()).filter((reg:string)=>reg&&!deleted.includes(reg))).size}
