   try{saved=JSON.parse(localStorage.getItem(`aa-garage-${type}s-${customer.name}`)||'[]')}catch{}
    return saved.map(document=>{const jobNames=(document.jobs||[]).map((job:any)=>String(job.name||'').trim()).filter(Boolean);return{id:document.id,customerId:customer.id,customer:customer.name,vehicle:document.vehicle||'Not recorded',detail:jobNames.length?jobNames.join(' · '):`${(document.jobs||[]).length} job${(document.jobs||[]).length===1?'':'s'}`,status:section==='quotes'?'Estimate':'Invoice',date:document.createdAt?new Date(document.createdAt).toLocaleDateString('en-IE'):'Not recorded'}});
