function countFor(section:Section,all:CustomerJob[],scope:CustomerJob[]){if(section==='vehicles'){const id=sessionStorage.getItem('aa-current-garage-customer-id');let record:any={id,vehicles:[],jobs:all};try{record={...(JSON.parse(localStorage.getItem('aa-garage-customer-records-v1')||'[]').find((item:any)=>item.id===id)||record),id,jobs:all}}catch{}return savedVehicleCount(record)}if(section==='contacts')return 2;if(section==='profile'||section==='monthly-statement'||section==='notes')return'';if(section==='messages')return scope.reduce((sum,job)=>sum+job.messages,0);if(section==='quotes'||section==='jobs'||section==='invoices'||section==='payments')return savedRecordCount(section,all);return scope.length}
function Profile({customer}:any){return <div className="customerPanel"><div className="panelHeading"><UserRound/><div><h3>Customer details</h3><p>The main record shared by every linked vehicle.</p></div></div><div className="customerDetails"><label><span>Full name</span><b>{customer.name}</b></label>{customer.company&&<label><span>Company name</span><b>{customer.company}</b></label>}<label><span>Mobile number</span><b>{customer.phone||'Not recorded'}</b></label><label><span>Email address</span><b>{customer.email}</b></label><label><span>Address</span><b>{customer.address}</b></label></div></div>}
function MonthlyStatement({customer,jobs}:{customer:any;jobs:CustomerJob[]}){const[sent,setSent]=useState(false),invoices=jobs.length*145,payments=jobs.length*100,credits=0,balance=invoices-payments-credits,download=()=>{const body=[`Monthly statement · August 2026`,customer.name,`Invoices: €${invoices.toFixed(2)}`,`Payments: €${payments.toFixed(2)}`,`Credits: €${credits.toFixed(2)}`,`Outstanding balance: €${balance.toFixed(2)}`].join('\n'),url=URL.createObjectURL(new Blob([body],{type:'text/plain'})),link=document.createElement('a');link.href=url;link.download=`${customer.name.replace(/\s+/g,'-').toLowerCase()}-statement-2026-08.txt`;link.click();URL.revokeObjectURL(url)};return <div className="customerPanel"><div className="panelHeading"><FileText/><div><h3>Monthly statement</h3><p>Invoices, payments, credits and balance for this customer.</p></div></div><div className="monthlyStatementBody"><b className="statementPeriod">August 2026</b><div className="statementTotals"><span><small>INVOICES</small><b>€{invoices.toFixed(2)}</b></span><span><small>PAYMENTS</small><b>€{payments.toFixed(2)}</b></span><span><small>CREDITS</small><b>€{credits.toFixed(2)}</b></span><span className="statementBalance"><small>OUTSTANDING</small><b>€{balance.toFixed(2)}</b></span></div><div className="statementActions"><button onClick={download}>Download statement</button><button onClick={()=>setSent(true)}>Send to {customer.email}</button></div>{sent&&<p className="statementSent">Statement prepared for sending to {customer.email}.</p>}</div></div>}
