function Vehicles({customerId,startAdding,vehicles,selected,choose}:{customerId:string;startAdding:boolean;vehicles:any[];selected:string|null;choose:(reg:string)=>void}){const key=`aa-garage-vehicles-${customerId}`,[adding,setAdding]=useState(startAdding),[lookupMessage,setLookupMessage]=useState(''),[draft,setDraft]=useState(blankVehicle()),[saved,setSaved]=useState<VehicleRecord[]>(()=>{try{const stored=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(stored))return stored.map(item=>({...item,extraDetails:item.extraDetails||{}}))}catch{}return[]}),[vehicleToDelete,setVehicleToDelete]=useState<string|null>(null),[deletedRegs,setDeletedRegs]=useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem(`aa-garage-deleted-vehicles-${customerId}`)||'[]')}catch{return[]}});useEffect(()=>{if(startAdding){setAdding(true);localStorage.removeItem('aa-pending-add-vehicle-customer');setTimeout(()=>document.querySelector('.vehicleForm')?.scrollIntoView({behavior:'smooth',block:'start'}),0)}},[startAdding,customerId]);const base=Array.from(new Map(vehicles.filter(item=>!deletedRegs.includes(String(item.reg).toUpperCase())).map(item=>[item.reg,item])).values()),deleteVehicle=(reg:string)=>{const normalised=reg.toUpperCase(),nextSaved=saved.filter(item=>item.reg.toUpperCase()!==normalised),nextDeleted=[...new Set([...deletedRegs,normalised])];setSaved(nextSaved);setDeletedRegs(nextDeleted);localStorage.setItem(key,JSON.stringify(nextSaved));localStorage.setItem(`aa-garage-deleted-vehicles-${customerId}`,JSON.stringify(nextDeleted));let records:any[]=[];try{records=JSON.parse(localStorage.getItem('aa-garage-customer-records-v1')||'[]')}catch{}localStorage.setItem('aa-garage-customer-records-v1',JSON.stringify(records.map(record=>record.id===customerId?{...record,vehicles:(record.vehicles||[]).filter((vehicle:any)=>String(vehicle.reg).toUpperCase()!==normalised)}:record)));setVehicleToDelete(null);window.dispatchEvent(new Event('aa-garage-customers-updated'))},lookup=()=>{const registration=draft.reg.trim().toUpperCase(),match=base.find(item=>item.reg.toUpperCase()===registration)||saved.find(item=>item.reg.toUpperCase()===registration);if(!registration){setLookupMessage('Enter a registration before running the lookup.');return}if(!match){setLookupMessage('No connected VRN service yet. You can enter the vehicle details manually.');return}const name='vehicle'in match?match.vehicle:`${match.make} ${match.model}`,parts=name.trim().split(/\s+/);setDraft(current=>({...current,reg:registration,make:'make'in match?match.make:parts[0]||'',model:'model'in match?match.model:parts.slice(1).join(' '),year:'year'in match?match.year:current.year,vin:'vin'in match?match.vin:current.vin,engineCc:'engineCc'in match?match.engineCc:current.engineCc,fuelType:'fuelType'in match?match.fuelType:current.fuelType,colour:'colour'in match?match.colour:current.colour,notes:'notes'in match?match.notes:current.notes,extraDetails:'extraDetails'in match?match.extraDetails:current.extraDetails}));setLookupMessage('Vehicle details found and populated. Check them before saving.')},save=(event:any)=>{event.preventDefault();const record:VehicleRecord={...draft,id:`vehicle-${Date.now()}`,reg:draft.reg.trim().toUpperCase()};const next=[...saved.filter(item=>item.reg!==record.reg),record];setSaved(next);localStorage.setItem(key,JSON.stringify(next));setDraft(blankVehicle());setLookupMessage('');setAdding(false)};return <div className="customerPanel">{vehicleToDelete&&<div className="customerDeleteConfirmation" role="dialog" aria-modal="true" aria-labelledby="delete-vehicle-title"><div><strong id="delete-vehicle-title">Delete vehicle {vehicleToDelete}?</strong><p>This removes it from this customer's active vehicle list. Existing job history will be kept for audit records.</p><div><button type="button" onClick={()=>setVehicleToDelete(null)}>Cancel</button><button type="button" className="confirmDeleteCustomer" onClick={()=>deleteVehicle(vehicleToDelete)}>Delete vehicle</button></div></div></div>}<div className="panelHeading"><Car/><div><h3>Vehicles</h3><p>Select a vehicle to filter every other category to it.</p></div><button className="addContactButton" onClick={()=>setAdding(true)}><Plus/>Add new vehicle</button></div>{adding&&<form className="vehicleForm" onSubmit={save}><h4>Add vehicle</h4><section className="vehicleLookup"><label><span>Registration <i>*</i></span><input required value={draft.reg} onChange={event=>setDraft({...draft,reg:event.target.value.toUpperCase()})} placeholder="Enter registration"/></label><button type="button" onClick={lookup}><Search/>VRN lookup</button>{lookupMessage&&<p role="status">{lookupMessage}</p>}</section><VehicleDropdown label="Make" value={draft.make} options={Object.keys(vehicleModels)} onChange={value=>setDraft({...draft,make:value,model:vehicleModels[value]?.includes(draft.model)?draft.model:""})}/><VehicleDropdown label="Model" value={draft.model} disabled={!draft.make} options={vehicleModels[draft.make]||[]} onChange={value=>setDraft({...draft,model:value})}/><label><span>Year</span><input inputMode="numeric" value={draft.year} onChange={event=>setDraft({...draft,year:event.target.value})}/></label><label><span>VIN</span><input value={draft.vin} onChange={event=>setDraft({...draft,vin:event.target.value.toUpperCase()})}/></label><label><span>Engine CC</span><input inputMode="numeric" value={draft.engineCc} onChange={event=>setDraft({...draft,engineCc:event.target.value})}/></label><label><span>Fuel type</span><input value={draft.fuelType} onChange={event=>setDraft({...draft,fuelType:event.target.value})}/></label><label><span>Colour</span><input value={draft.colour} onChange={event=>setDraft({...draft,colour:event.target.value})}/></label><label className="vehicleNotes"><span>Vehicle notes</span><textarea value={draft.notes} onChange={event=>setDraft({...draft,notes:event.target.value})} placeholder="Add notes specific to this vehicle"/></label>{Object.keys(draft.extraDetails).length>0&&<section className="vehicleExtraDetails"><h5>Additional VRN lookup information</h5>{Object.entries(draft.extraDetails).map(([label,value])=><label key={label}><span>{label}</span><input readOnly value={value}/></label>)}</section>}<div className="vehicleFormActions"><button type="button" onClick={()=>{setAdding(false);setLookupMessage('');setDraft(blankVehicle())}}>Cancel</button><button type="submit">Save vehicle</button></div></form>}<div className="vehicleCards">{[...saved,...base.filter(item=>!saved.some(record=>record.reg===item.reg))].filter((item:any)=>!deletedRegs.includes(String(item.reg).toUpperCase())).map((item:any)=><article className={selected===item.reg?'active':''} key={item.reg}><button className="openVehicleButton" onClick={()=>choose(item.reg)}><Car/><span><b>{item.reg}</b><small>{item.make?`${item.make} ${item.model}`:item.vehicle}</small>{item.year&&<small>{item.year} · {item.fuelType} · {item.colour}</small>}{item.extraDetails&&Object.keys(item.extraDetails).length>0&&<small>{Object.keys(item.extraDetails).length} additional lookup details saved</small>}</span><em>Open vehicle →</em></button><button type="button" className="deleteVehicleButton" onClick={event=>{event.stopPropagation();setVehicleToDelete(item.reg)}}>Delete vehicle</button></article>)}</div></div>}
function VehicleOverview({customer,reg,jobs,back,openSection}:{customer:any;reg:string;jobs:CustomerJob[];back:()=>void;openSection:(target:'quotes'|'jobs'|'invoices',id:string)=>void}){
 const normalise=(value:string)=>String(value||'').split(' · ')[0].trim().toUpperCase(),matches=(value:string)=>normalise(value)===reg.toUpperCase();
 let estimates:any[]=[],invoices:any[]=[],jobCards:any[]=[];
 try{estimates=JSON.parse(localStorage.getItem(`aa-garage-quotes-${customer.name}`)||'[]').filter((item:any)=>matches(item.vehicle))}catch{}
 try{invoices=JSON.parse(localStorage.getItem(`aa-garage-invoices-${customer.name}`)||'[]').filter((item:any)=>matches(item.vehicle))}catch{}
 try{jobCards=JSON.parse(localStorage.getItem('aa-garage-created-job-cards')||'[]').filter((item:any)=>item.customer===customer.name&&matches(item.vehicle))}catch{}
 const vehicle=(customer.vehicles||[]).find((item:any)=>normalise(item.reg)===reg.toUpperCase()),description=vehicle?[vehicle.make,vehicle.model].filter(Boolean).join(' '):jobs.find(job=>job.reg.toUpperCase()===reg.toUpperCase())?.vehicle||'Vehicle';
 const group=(title:string,Icon:any,items:any[],target:'quotes'|'jobs'|'invoices',empty:string)=><section className="vehicleRecordGroup"><header><Icon/><h4>{title}</h4><b>{items.length}</b><button type="button" onClick={()=>openSection(target,'__create__')}>Create {target==='quotes'?'estimate':target==='jobs'?'job card':'invoice'}</button></header><div>{items.length?items.map(item=><button type="button" key={item.id} onClick={()=>openSection(target,item.id)}><strong>{item.id}</strong><span>{(item.jobs||[]).map((job:any)=>job.name).filter(Boolean).join(', ')||item.requestedWork||'Open record'}</span><small>{item.createdAt?new Date(item.createdAt).toLocaleDateString('en-IE'):'Date not recorded'} · Open →</small></button>):<p>{empty}</p>}</div></section>;
 return <div className="vehicleOverview"><header className="vehicleOverviewHeader"><Car/><div><small>VEHICLE RECORD</small><h3>{reg} · {description}</h3><p>{customer.name}</p></div><button type="button" onClick={back}>← Back to vehicles</button></header><div className="vehicleRecordGroups">{group('Estimates',FileText,estimates,'quotes','No estimates for this vehicle.')}{group('Job cards',ClipboardList,jobCards,'jobs','No job cards for this vehicle.')}{group('Invoices',Receipt,invoices,'invoices','No invoices for this vehicle.')}</div></div>
}
function Jobs({jobs}:{jobs:CustomerJob[]}){
 return <div className="customerPanel garageDocumentUnified"><GarageDocumentWorkspace type="invoice" variant="job-card" jobs={jobs}/></div>
}
function Records({title,jobs,prefix,empty}:{title:string;jobs:CustomerJob[];prefix:string;empty:string}){
 if(prefix==='QUO')return <div className="customerPanel garageDocumentUnified"><GarageDocumentWorkspace type="quote" jobs={jobs}/></div>;
 if(title==='Invoices')return <div className="customerPanel garageDocumentUnified"><GarageDocumentWorkspace type="invoice" jobs={jobs}/></div>;
 if(title==='Payments'){
  const customerId=sessionStorage.getItem('aa-current-garage-customer-id');let customerName=jobs[0]?.customer||'';
  if(!customerName&&customerId){try{const records=JSON.parse(localStorage.getItem('aa-garage-customer-records-v1')||'[]');customerName=records.find((record:any)=>record.id===customerId)?.name||''}catch{}}
  let invoices:any[]=[];try{invoices=JSON.parse(localStorage.getItem(`aa-garage-invoices-${customerName}`)||'[]')}catch{}
  const payments=invoices.flatMap(invoice=>(invoice.payments||[]).map((payment:any,index:number)=>({paymentId:payment.id||'',invoiceId:invoice.id,customer:invoice.customer,vehicle:invoice.vehicle,amount:Number(payment.amount||0),date:payment.date||'',method:payment.method||'Method not recorded',key:`${invoice.id}-${index}`}))).map((payment,index)=>({...payment,paymentId:payment.paymentId||`PAY-${String(index+1).padStart(5,'0')}`}));
  return <div className="customerPanel"><div className="panelHeading"><WalletCards/><div><h3>Payments</h3><p>Every payment has its own reference and is linked to its invoice.</p></div></div><div className="recordList paymentRecordList">{payments.length?payments.map(payment=><article key={payment.key}><b className="paymentNumber">{payment.paymentId}</b><button type="button" className="paymentInvoiceLink" onClick={()=>window.dispatchEvent(new CustomEvent('aa-open-customer-document',{detail:{customer:payment.customer||customerName,section:'invoices',id:payment.invoiceId}}))}>{payment.invoiceId}</button><strong>{payment.method} · €{payment.amount.toFixed(2)}</strong><span>{payment.date?new Date(`${payment.date}T00:00:00`).toLocaleDateString('en-IE'):'Date not recorded'} · {payment.vehicle}</span></article>):<p className="customerEmpty">{empty}</p>}</div></div>
 }
 return <div className="customerPanel"><div className="panelHeading"><Receipt/><div><h3>{title}</h3><p>Filtered to the customer or selected vehicle.</p></div></div><div className="recordList">{jobs.length?jobs.map((job,index)=><article key={job.id}><b>{prefix}-{String(index+1).padStart(4,'0')}</b><strong>{job.reg} · {job.work}</strong><span>{job.vehicle} · {job.booked}</span></article>):<p className="customerEmpty">{empty}</p>}</div></div>
}
function Notes({jobs}:{jobs:CustomerJob[]}){return <div className="customerPanel"><div className="panelHeading"><StickyNote/><div><h3>Notes</h3><p>Customer and vehicle-specific notes stay with the correct record.</p></div></div><div className="recordList">{jobs.flatMap(job=>job.history.map(note=><article key={`${job.id}-${note}`}><b>{job.reg}</b><strong>{note}</strong><span>{job.vehicle}</span></article>))}</div></div>}
